    "home_faq_q1": "एआई पोषण मूल्याङ्कन कितना सटीक है?",
    "home_faq_a1": "न्यूट्री-एआई एनएचएएनईएस क्लिनिकल डेटासेट पर 94.8% F1-स्कोर परिशुद्धता प्राप्त करता है। हमारा रैंडम फॉरेस्ट मॉडल हज़ारों वास्तविक रोगियों के रिकॉर्ड पर प्रशिक्षित है।",
    "home_faq_q2": "क्या मैं सीधे ब्लड टेस्ट पीडीएफ वृत्तान्तः अपलोड कर सकता हूँ?",
    "home_faq_a2": "हाँ! हमारा मल्टी-मॉडल जेमिनी विज़न ओसीआर लैब पीडीएफ फ़ाइलों को पार्स करता है और तुरंत न्यून्ता जोखिम विश्लेषणम् के लिए आपके रक्त मार्कर मानों को स्वतः भरता है।",
    "home_faq_q3": "क्या न्यूट्री-एआई शाकाहारी और वीगन आहार का समर्थन करता है?",
    "home_faq_a3": "बिल्कुल! हमारा मील अनुशंसक जैविक पोषण शील्ड शामिल करता है जो सभी आहार प्राथमिकताओं के लिए पूर्ण प्रोटीन, आयरन और बी12 की पर्याप्तता सुनिश्चित करता है।",
    "home_faq_q4": "PWA ऐप बिना ऐप स्टोर डाउनलोड के कैसे काम करता है?",
    "home_faq_a4": "न्यूट्री-एआई प्रोग्रेसिव वेब ऐप तकनीक के साथ बनाया गया है। बस क्रोम या सफारी में साइट पर जाएं और नेटिव ऐप जैसा अनुभव पाने के लिए 'इंस्टॉल' पर टैप करें।",
